css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .44); position: relative; }
.loader span { position: absolute; bottom: 2%; width: 17%; height: 46%; border-radius: 4px; box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--accent) 60%, transparent); background: color-mix(in srgb, var(--accent) 12%, transparent); animation: hop-lit calc(var(--loader-speed) * 2.5) ease-in-out infinite; }
.loader span:nth-of-type(1) { left: 1%; }
.loader span:nth-of-type(2) { left: 21%; animation-delay: calc(var(--loader-speed) * .5); }
.loader span:nth-of-type(3) { left: 41%; animation-delay: calc(var(--loader-speed) * 1); }
.loader span:nth-of-type(4) { left: 61%; animation-delay: calc(var(--loader-speed) * 1.5); }
.loader span:nth-of-type(5) { left: 81%; animation-delay: calc(var(--loader-speed) * 2); }
.loader .marker { position: absolute; left: 5%; bottom: 12%; width: 9%; height: 26%; border-radius: 50%; background: radial-gradient(circle at 38% 34%, color-mix(in srgb, #fff 40%, var(--accent-2)), var(--accent-2)); animation: hop-jump calc(var(--loader-speed) * 2.5) cubic-bezier(.4, 0, .5, 1) infinite; }
@keyframes hop-jump { 0%, 6% { transform: translate(0, 0); } 13% { transform: translate(111%, -150%); } 20%, 26% { transform: translate(222%, 0); } 33% { transform: translate(333%, -150%); } 40%, 46% { transform: translate(444%, 0); } 53% { transform: translate(555%, -150%); } 60%, 66% { transform: translate(667%, 0); } 73% { transform: translate(778%, -150%); } 80%, 88% { transform: translate(889%, 0); } 95% { transform: translate(445%, -200%); } 100% { transform: translate(0, 0); } }
@keyframes hop-lit { 0%, 8% { background: color-mix(in srgb, var(--accent-2) 48%, transparent); } 18%, 100% { background: color-mix(in srgb, var(--accent) 10%, transparent); } }
